fun <E : PaymentEvent> subscribeOnce(type: KClass<E>, handler: Handler<E>): Subscription {
    val fired = AtomicBoolean()
    val handle = AtomicReference<Subscription>()
    handle.set(subscribe(type) { event ->
        if (fired.compareAndSet(false, true)) {          // 1. only the first event wins
            try { handler.handle(event) }                // 2. do the work
            finally { handle.get()?.close() }            // 3. stop further deliveries
        }
    })
    if (fired.get()) handle.get().close()                // an event won before the handle was set
    return handle.get()
}

inline fun <reified E : PaymentEvent> subscribeOnce(handler: Handler<E>): Subscription =
    subscribeOnce(E::class, handler)

