@DslMarker
@Target(AnnotationTarget.CLASS)
annotation class EventsDsl

@EventsDsl
class SubscriptionsBuilder private constructor(private val bus: EventBus) {
    private val pending = mutableListOf<Pending<*>>()

    fun <E : PaymentEvent> on(type: KClass<E>, handler: Handler<E>) { pending += Pending(type, handler) }
    fun <E : PaymentEvent> on(type: Class<E>, handler: Handler<E>) = on(type.kotlin, handler)
    inline fun <reified E : PaymentEvent> on(crossinline handler: (E) -> Unit) = on(E::class, Handler { handler(it) })

    private fun commit(): Subscription {
        val handles = pending.map { it.subscribeTo(bus) }
        return Subscription { handles.asReversed().forEach(Subscription::close) }
    }

    private class Pending<E : PaymentEvent>(val type: KClass<E>, val handler: Handler<E>) {
        fun subscribeTo(bus: EventBus) = bus.subscribe(type, handler)
    }

    companion object {
        fun build(bus: EventBus, block: SubscriptionsBuilder.() -> Unit) = SubscriptionsBuilder(bus).apply(block).commit()
    }
}

fun EventBus.subscriptions(block: SubscriptionsBuilder.() -> Unit): Subscription = SubscriptionsBuilder.build(this, block)
